10	/// Marks the start or end of a locatable element.
11	#[derive(Clone, PartialEq, Hash)]
12	pub enum Tag {
13	    /// The stored element starts here.
14	    ///
15	    /// Content placed in a tag **must** have a [`Location`] or there will be
16	    /// panics.
17	    Start(Content, TagFlags),
18	    /// The element with the given location and key hash ends here.
19	    ///
20	    /// Note: The key hash is stored here instead of in `Start` simply to make
21	    /// the two enum variants more balanced in size, keeping a `Tag`'s memory
22	    /// size down. There are no semantic reasons for this.
23	    End(Location, u128, TagFlags),
24	}
25	
26	impl Tag {
27	    /// Access the location of the tag.
28	    pub fn location(&self) -> Location {
29	        match self {
30	            Tag::Start(elem, ..) => elem.location().unwrap(),
31	            Tag::End(loc, ..) => *loc,
32	        }
33	    }
34	}
