36	impl Debug for Tag {
37	    fn fmt(&self, f: &mut Formatter) -> fmt::Result {
38	        let loc = self.location();
39	        match self {
40	            Tag::Start(elem, ..) => write!(f, "Start({:?}, {loc:?})", elem.elem().name()),
41	            Tag::End(..) => write!(f, "End({loc:?})"),
42	        }
43	    }
