735	    /// Create a new fast page counter, starting at 1.
736	    pub fn new() -> Self {
737	        Self { physical: NonZeroUsize::ONE, logical: 1 }
738	    }
739	
740	    /// Get the current physical page counter state.
741	    pub fn physical(&self) -> NonZeroUsize {
742	        self.physical
743	    }
744	
745	    /// Get the current logical page counter state.
746	    pub fn logical(&self) -> u64 {
747	        self.logical
748	    }
749	
750	    /// Advance past a page.
751	    pub fn visit(&mut self, engine: &mut Engine, page: &Frame) -> SourceResult<()> {
752	        for (_, item) in page.items() {
753	            match item {
754	                FrameItem::Group(group) => self.visit(engine, &group.frame)?,
755	                FrameItem::Tag(Tag::Start(elem, _)) => {
756	                    let Some(elem) = elem.to_packed::<CounterUpdateElem>() else {
757	                        continue;
758	                    };
759	                    if elem.key == CounterKey::Page {
760	                        let mut state = CounterState(smallvec![self.logical]);
761	                        state.update(
762	                            engine,
763	                            Spanned::new(elem.update.clone(), elem.span()),
764	                        )?;
765	                        self.logical = state.first();
766	                    }
767	                }
768	                _ => {}
769	            }
770	        }
771	
772	        Ok(())
773	    }
774	
775	    /// Step past a page _boundary._
776	    pub fn step(&mut self) {
777	        self.physical = self.physical.saturating_add(1);
778	        self.logical += 1;
779	    }
780	}
